class Provider {
  getSettings() {
    return { episodeServers: ["local-proof"], supportsDub: false };
  }

  async search(options) {
    return [{
      id: "phase4-local-anime",
      title: options.query || "Phase 4 Local Anime",
      url: "http://127.0.0.1:18846/catalogue/phase4-local-anime",
      subOrDub: "sub"
    }];
  }

  async findEpisodes(id) {
    return [{
      id: id + "-episode-1",
      number: 1,
      url: "http://127.0.0.1:18846/catalogue/phase4-local-anime/1",
      title: "Episode 1"
    }];
  }

  async findEpisodeServer(episode, server) {
    return {
      server: server,
      headers: { "X-Phase4-Proof": "provider-header" },
      videoSources: [{
        url: "http://127.0.0.1:18846/phase4-proof.mp4",
        type: "mp4",
        quality: "720p",
        subtitles: [{
          id: "ja",
          url: "http://127.0.0.1:18846/phase4-proof.vtt",
          language: "ja",
          isDefault: true
        }]
      }]
    };
  }
}
